CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK(slug='meridionale-impianti'), name text NOT NULL, branding jsonb NOT NULL DEFAULT '{}',approval_required boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app_users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),auth_subject text UNIQUE,email text NOT NULL UNIQUE,display_name text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(organization_id uuid REFERENCES organizations(id),user_id uuid REFERENCES app_users(id),role text NOT NULL CHECK(role IN ('org_admin','member')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,user_id));
CREATE TABLE platform_admins(user_id uuid PRIMARY KEY REFERENCES app_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE card_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,layout jsonb NOT NULL DEFAULT '{}',is_default boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,organization_id));
CREATE TABLE cards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),template_id uuid,owner_id uuid REFERENCES app_users(id),slug text NOT NULL CHECK(slug ~ '^[a-z0-9-]+$'),data jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','published','rejected','suspended')),revision integer NOT NULL DEFAULT 1,published_data jsonb,published_revision integer,published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,slug),FOREIGN KEY(template_id,organization_id) REFERENCES card_templates(id,organization_id));
CREATE TABLE card_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),card_id uuid NOT NULL REFERENCES cards(id),reviewer_id uuid NOT NULL REFERENCES app_users(id),decision text NOT NULL CHECK(decision IN ('approved','rejected')),note text,created_at timestamptz NOT NULL DEFAULT now());
WITH org AS (INSERT INTO organizations(slug,name,branding) VALUES('meridionale-impianti','Meridionale Impianti S.p.A.','{"accent":"#147ea4","primary":"#102b53","template":"mi-original","website":"https://www.merimp.com","address":"Via Senatore Simonetta 26/D, 20867 Caponago (MB), Italia"}') RETURNING id) INSERT INTO card_templates(organization_id,name,layout,is_default) SELECT id,'MI originale','{"source":"template.html","immutable_reference":true}',true FROM org;
WITH admin AS (INSERT INTO app_users(email,display_name) VALUES('antonio.astuti@merimp.com','Antonio Astuti') RETURNING id) INSERT INTO memberships(organization_id,user_id,role) SELECT o.id,a.id,'org_admin' FROM organizations o CROSS JOIN admin a;
